CREATE TYPE "Role" AS ENUM ('CUSTOMER','PROFESSIONAL','ADMIN');
CREATE TYPE "BookingStatus" AS ENUM ('REQUESTED','ACCEPTED','CONFIRMED','ON_THE_WAY','ARRIVED','SERVICE_STARTED','COMPLETED','CANCELLED','DISPUTED');
CREATE TABLE "User" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'CUSTOMER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Category" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,CONSTRAINT "Category_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Category_name_key" ON "Category"("name"); CREATE UNIQUE INDEX "Category_slug_key" ON "Category"("slug");
CREATE TABLE "Service" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"categoryId" TEXT NOT NULL,CONSTRAINT "Service_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Booking" ("id" TEXT NOT NULL,"customerId" TEXT NOT NULL,"serviceId" TEXT NOT NULL,"status" "BookingStatus" NOT NULL DEFAULT 'REQUESTED',"scheduledAt" TIMESTAMP(3) NOT NULL,"address" TEXT NOT NULL,"problem" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Booking_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Service" ADD CONSTRAINT "Service_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Booking" ADD CONSTRAINT "Booking_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Booking" ADD CONSTRAINT "Booking_serviceId_fkey" FOREIGN KEY ("serviceId") REFERENCES "Service"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
